<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<script>
const mapItems=@json($mapItems);
const favoriteKey='ozman_real_estate_favorites';const compareKey='ozman_real_estate_compare_{{ $company?->id ?? 'global' }}';
const readIds=key=>{try{return JSON.parse(localStorage.getItem(key)||'[]').map(Number)}catch(e){return[]}};const saveIds=(key,ids)=>localStorage.setItem(key,JSON.stringify([...new Set(ids)]));
function refreshFavorites(){const ids=readIds(favoriteKey);document.querySelectorAll('[data-favorite]').forEach(b=>{const active=ids.includes(Number(b.dataset.favorite));b.classList.toggle('active',active);b.textContent=active?'♥':'♡'})}
document.querySelectorAll('[data-favorite]').forEach(b=>b.addEventListener('click',()=>{let ids=readIds(favoriteKey),id=Number(b.dataset.favorite);ids=ids.includes(id)?ids.filter(x=>x!==id):[...ids,id];saveIds(favoriteKey,ids);refreshFavorites()}));
function refreshCompare(){const ids=readIds(compareKey).slice(0,4);document.querySelectorAll('[data-compare]').forEach(c=>c.checked=ids.includes(Number(c.value)));document.getElementById('compare-count').textContent=ids.length;document.getElementById('compare-link').href='{{ route('real-estate.compare') }}?ids='+ids.join(',');document.getElementById('compare-bar').classList.toggle('show',ids.length>1)}
document.querySelectorAll('[data-compare]').forEach(c=>c.addEventListener('change',()=>{let ids=readIds(compareKey),id=Number(c.value);if(c.checked&&!ids.includes(id)&&ids.length<4)ids.push(id);if(!c.checked)ids=ids.filter(x=>x!==id);saveIds(compareKey,ids);refreshCompare()}));refreshFavorites();refreshCompare();
function updateSort(value){const u=new URL(location.href);value?u.searchParams.set('sort',value):u.searchParams.delete('sort');location.href=u}
document.getElementById('map-toggle').onclick=()=>document.getElementById('market-layout').classList.add('map-mode');document.getElementById('list-toggle').onclick=()=>document.getElementById('market-layout').classList.remove('map-mode');
const channel=document.getElementById('alert-channel'),contact=document.getElementById('alert-contact');channel.onchange=()=>{contact.type=channel.value==='email'?'email':'tel';contact.name=channel.value==='email'?'email':'phone';contact.placeholder=channel.value==='email'?'{{ $labels['email'] }}':'{{ $labels['whatsapp'] }}'};
if(window.L&&mapItems.length){const map=L.map('property-map');L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);const bounds=[];mapItems.forEach(p=>{bounds.push([p.lat,p.lng]);L.marker([p.lat,p.lng]).addTo(map).bindPopup(`<div class="map-popup"><a href="${p.url}">${p.title}</a><br>${Number(p.price).toLocaleString()} ${p.currency}</div>`)});map.fitBounds(bounds,{padding:[30,30],maxZoom:15})}else document.getElementById('property-map').innerHTML='<div class="empty">{{ $labels['no_results'] }}</div>';
</script>
